@app.get("/api/students")
def list_students():
    return {"success": True, "total": len(students), "data": students}

@app.get("/api/students/{student_id}")
def get_student(student_id: int):
    for s in students:
        if s["id"] == student_id:
            return {"success": True, "data": s}
    raise HTTPException(status_code=404, detail="Student not found")

@app.post("/api/students", status_code=201)
def create_student(student: StudentCreate):
    global next_id
    new = {"id": next_id, **student.model_dump()}
    students.append(new)
    next_id += 1
    return {"success": True, "data": new}

@app.put("/api/students/{student_id}")
def update_student(student_id: int, updates: StudentUpdate):
    for s in students:
        if s["id"] == student_id:
            for key, value in updates.model_dump(exclude_unset=True).items():
                s[key] = value
            return {"success": True, "data": s}
    raise HTTPException(status_code=404, detail="Student not found")

@app.delete("/api/students/{student_id}")
def delete_student(student_id: int):
    for i, s in enumerate(students):
        if s["id"] == student_id:
            removed = students.pop(i)
            return {"success": True, "message": f"Deleted {removed['name']}"}
    raise HTTPException(status_code=404, detail="Student not found")
